package dev.unbox.client;

import com.google.gson.*;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.*;
import net.minecraft.network.chat.Component;
import java.nio.file.*;
import java.util.*;

/** Local skin picker. The launcher performs authenticated uploads and returns an acknowledgement. */
public final class SkinLibraryScreen extends Screen {
 private static final Path ROOT=Platform.gameDir();private static final Gson JSON=new Gson();
 private final Screen parent;private final PlayerPreview preview=new PlayerPreview();private List<JsonObject> skins=List.of();
 private String equippedLogo="logo";private boolean assetPending;private String assetSignature="";private int logoPage;
 private String accountId="",message="",selected="";private int page,x,y;private float scale=1;private boolean dragging;private double dragX;private String pending="";private long pendingAt;
 public SkinLibraryScreen(Screen parent){super(Component.literal("Skins"));this.parent=parent;}
 @Override protected void init(){clearWidgets();scale=Math.min(1,Math.min(width/620f,height/460f));x=(int)(width/scale/2)-280;y=(int)(height/scale/2)-205;load();page=Math.max(0,Math.min(page,Math.max(0,skins.size()-5)));for(int i=page;i<Math.min(skins.size(),page+5);i++){var skin=skins.get(i);String id=text(skin,"id");var action=add(x+18,y+82+(i-page)*48,38,38,text(skin,"name"),false,id.equals(selected),()->{if(pending.isEmpty())apply(id);});action.skin=skin;}
  var redeem=add(x+470,y+15,72,24,"Redeem",false,false,()->minecraft.setScreen(new RedeemScreen(this)));redeem.active=RedeemScreen.eligible();
  List<JsonObject> logos=new ArrayList<>();JsonObject basic=new JsonObject();basic.addProperty("id","");basic.addProperty("name","Unbox");logos.add(basic);JsonObject assets=SocialBridge.view.has("assets")&&SocialBridge.view.get("assets").isJsonObject()?SocialBridge.view.getAsJsonObject("assets"):new JsonObject();String equipped="";
  if(RedeemScreen.eligible()&&assets.has("items"))for(var item:assets.getAsJsonArray("items")){var o=item.getAsJsonObject();if(text(o,"kind").equals("logo"))logos.add(o);}
  if(assets.has("equipment"))for(var entry:assets.getAsJsonArray("equipment")){var o=entry.getAsJsonObject();if(text(o,"slot").equals("logo"))equipped=text(o,"item");}
  equippedLogo=RedeemScreen.eligible()&&Set.of("unbox-creator-crown","unbox-fluttering-cash").contains(equipped)?equipped:"logo";
  logoPage=Math.min(logoPage,Math.max(0,(logos.size()-1)/6));for(int n=logoPage*6;n<Math.min(logos.size(),logoPage*6+6);n++){var item=logos.get(n);String id=text(item,"id");int i=n-logoPage*6;var button=add(x+320+(i%2)*112,y+82+(i/2)*78,102,68,text(item,"name"),true,id.equals(equipped),()->{if(SocialBridge.command("equip-logo",id)){assetPending=true;message="Updating logo…";}});button.logo=Set.of("unbox-creator-crown","unbox-fluttering-cash").contains(id)?id:"logo";button.active=RedeemScreen.eligible()&&!SocialBridge.commandPending();}
  if(logos.size()>6){add(x+320,y+325,102,24,"Previous",false,false,()->{logoPage=Math.max(0,logoPage-1);init();});add(x+432,y+325,102,24,"Next",false,false,()->{logoPage=Math.min((logos.size()-1)/6,logoPage+1);init();});}
 }
 private void load(){try{Path p=ROOT.resolve("unbox-skin-library.json");if(!Files.isRegularFile(p)||Files.size(p)>256000)return;JsonObject v=JsonParser.parseString(Files.readString(p)).getAsJsonObject();accountId=text(v,"accountId");List<JsonObject> out=new ArrayList<>();if(v.has("skins"))for(var e:v.getAsJsonArray("skins"))out.add(e.getAsJsonObject());skins=out;if(v.has("active")&&v.get("active").isJsonObject()&&pending.isEmpty())selected=text(v.getAsJsonObject("active"),"id");}catch(Exception ignored){}}
 private void apply(String id){if(!pending.isEmpty())return;if(accountId.isEmpty()){message="Open the launcher and choose an account";return;}try{String request=UUID.randomUUID().toString();JsonObject c=new JsonObject();c.addProperty("requestId",request);c.addProperty("accountId",accountId);c.addProperty("id",id);c.addProperty("at",System.currentTimeMillis());write("unbox-skin-command.json",c);pending=request;pendingAt=System.currentTimeMillis();message="Applying through the launcher…";}catch(Exception e){message="Could not contact the launcher";}}
 @Override public void tick(){if(assetPending&&!SocialBridge.commandPending()){assetPending=false;message=SocialBridge.commandSucceeded()?"Logo equipped.":SocialBridge.message;}String sig=String.valueOf(SocialBridge.view.get("assets"))+RedeemScreen.eligible()+SocialBridge.commandPending();if(!sig.equals(assetSignature)){assetSignature=sig;init();}if(pending.isEmpty())return;if(System.currentTimeMillis()-pendingAt>20000){pending="";message="The launcher did not respond. Keep it open and retry.";return;}try{Path p=ROOT.resolve("unbox-skin-ack.json");if(!Files.isRegularFile(p)||Files.size(p)>8192)return;JsonObject a=JsonParser.parseString(Files.readString(p)).getAsJsonObject();if(!pending.equals(text(a,"requestId")))return;pending="";if(a.has("ok")&&a.get("ok").getAsBoolean()){load();init();}message=a.has("ok")&&a.get("ok").getAsBoolean()?"Skin applied. Rejoin to refresh it in this game.":text(a,"error");if(message.isEmpty())message="The launcher could not apply this skin.";}catch(Exception ignored){}}
 @Override public void extractBackground(GuiGraphicsExtractor g,int mx,int my,float delta){}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float delta){g.pose().pushMatrix();g.pose().scale(scale);int ux=(int)(mx/scale),uy=(int)(my/scale);PanelStyle.icon(g,"logo",x+17,y+15,25,PanelStyle.TEXT);PanelStyle.label(g,"SKINS",x+55,y+22,PanelStyle.TEXT);
  PanelStyle.label(g,"LOGOS",x+320,y+61,PanelStyle.MUTED);if(!RedeemScreen.eligible())PanelStyle.label(g,"Microsoft sign-in required to redeem",x+320,y+354,PanelStyle.MUTED);
  String name=minecraft.getUser().getName();int center=x+185;PanelStyle.icon(g,equippedLogo,center-PanelStyle.width(name)/2-24,y+58,18,PanelStyle.TEXT);PanelStyle.center(g,name,center,y+63,PanelStyle.TEXT);if(System.getProperty("unbox.accountKind","microsoft").equals("local")){int nx=center+PanelStyle.width(name)/2+9;PanelStyle.round(g,nx,y+61,13,13,6,0x70565e69);PanelStyle.label(g,"N",nx+3,y+63,PanelStyle.MUTED);}
  preview.draw(g,x+72,y+87,x+292,y+365,ux,uy,dragging);
  if(skins.isEmpty())PanelStyle.label(g,"Import skins in the launcher",x+80,y+382,PanelStyle.MUTED);for(int from=0,line=0;from<message.length();from+=48,line++)PanelStyle.label(g,message.substring(from,Math.min(from+48,message.length())),x+74,y+382+line*12,PanelStyle.MUTED);
  for(var child:children())if(child instanceof AbstractWidget w)w.extractRenderState(g,ux,uy,delta);g.pose().popMatrix();}
 @Override public boolean mouseScrolled(double mx,double my,double horizontal,double vertical){double ux=mx/scale,uy=my/scale;if(ux>=x+10&&ux<=x+67&&uy>=y+70&&uy<=y+330){int next=Math.max(0,Math.min(Math.max(0,skins.size()-5),page-(int)Math.signum(vertical)));if(next!=page){page=next;init();}return true;}return super.mouseScrolled(mx,my,horizontal,vertical);}
 @Override public boolean mouseClicked(MouseButtonEvent e,boolean doubled){double ux=e.x()/scale,uy=e.y()/scale;if(e.button()==0&&ux>=x+72&&ux<=x+292&&uy>=y+87&&uy<=y+365){dragging=true;dragX=ux;return true;}return super.mouseClicked(new MouseButtonEvent(ux,uy,e.buttonInfo()),doubled);}
 @Override public boolean mouseDragged(MouseButtonEvent e,double dx,double dy){double ux=e.x()/scale;if(dragging){preview.rotate((float)(ux-dragX));dragX=ux;return true;}return super.mouseDragged(new MouseButtonEvent(ux,e.y()/scale,e.buttonInfo()),dx/scale,dy/scale);}
 @Override public boolean mouseReleased(MouseButtonEvent e){if(dragging){dragging=false;return true;}return super.mouseReleased(new MouseButtonEvent(e.x()/scale,e.y()/scale,e.buttonInfo()));}
 @Override public boolean keyPressed(KeyEvent e){if(e.key()==org.lwjgl.glfw.GLFW.GLFW_KEY_RIGHT_SHIFT){onClose();return true;}return super.keyPressed(e);}
 @Override public void onClose(){minecraft.setScreen(parent);}@Override public boolean isPauseScreen(){return false;}
 private Action add(int x,int y,int w,int h,String label,boolean card,boolean selected,Runnable run){return addRenderableWidget(new Action(x,y,w,h,label,card,selected,run));}
 private static String text(JsonObject o,String k){return o.has(k)&&!o.get(k).isJsonNull()?o.get(k).getAsString():"";}
 private static void write(String name,JsonObject value)throws Exception{Path tmp=ROOT.resolve(".unbox-"+UUID.randomUUID()+".tmp");Files.writeString(tmp,JSON.toJson(value),StandardOpenOption.CREATE_NEW);Files.move(tmp,ROOT.resolve(name),StandardCopyOption.REPLACE_EXISTING);}
 private static final class Action extends AbstractWidget{private final Runnable run;private final boolean card,selected;private String logo;private JsonObject skin;Action(int x,int y,int w,int h,String text,boolean card,boolean selected,Runnable run){super(x,y,w,h,Component.literal(text));this.run=run;this.card=card;this.selected=selected;}@Override protected void extractWidgetRenderState(GuiGraphicsExtractor g,int mx,int my,float d){if(card||selected||isHoveredOrFocused())PanelStyle.round(g,getX(),getY(),width,height,5,selected?0xff43577e:isHoveredOrFocused()?0xff4b6088:0xc832353d);if(logo!=null){PanelStyle.icon(g,logo,getX()+width/2-17,getY()+6,34,0xffffffff);String label=getMessage().getString();PanelStyle.center(g,label.length()>17?label.substring(0,16)+"…":label,getX()+width/2,getY()+49,active?PanelStyle.TEXT:PanelStyle.MUTED);}else if(skin!=null){JsonObject face=skin.deepCopy();face.addProperty("id",UUID.nameUUIDFromBytes(text(skin,"id").getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());FriendsOverlay.drawFace(g,face,getX()+7,getY()+7);}else PanelStyle.center(g,getMessage().getString(),getX()+width/2,getY()+10,active?PanelStyle.TEXT:PanelStyle.MUTED);}@Override public void onClick(MouseButtonEvent e,boolean d){run.run();}@Override public boolean keyPressed(KeyEvent e){if(e.isConfirmation()&&active){run.run();return true;}return super.keyPressed(e);}@Override protected void updateWidgetNarration(NarrationElementOutput o){defaultButtonNarrationText(o);}}
}
